import numpy as np, random, time, os
os.environ['OMP_NUM_THREADS']='4'
random.seed(0)

def time_svd(shape, reps=3):
    rows,cols=shape
    t=0
    for _ in range(reps):
        A=np.random.randn(rows,cols)
        start=time.perf_counter(); np.linalg.svd(A, full_matrices=False); t+=time.perf_counter()-start
    return t/reps

def time_gram(shape, reps=3):
    rows,cols=shape
    t=0
    for _ in range(reps):
        A=np.random.randn(rows,cols)
        start=time.perf_counter();
        if rows>=cols:
            B=A.T@A; w,V=np.linalg.eigh(B); w=w[::-1]; V=V[:, ::-1]; s=np.sqrt(np.maximum(w,0)); U=(A@V)/s
        else:
            B=A@A.T; w,U=np.linalg.eigh(B); w=w[::-1]; U=U[:, ::-1]; s=np.sqrt(np.maximum(w,0)); V=(A.T@U)/s
        t+=time.perf_counter()-start
    return t/reps
shapes=[(200,200),(200,250),(200,300),(200,350),(200,400),(250,200),(300,200),(350,200),(400,200),(250,250),(300,300),(400,400)]
