def sqrtm_newton_higham(A, max_iter=10, tol=1e-10):
    A = A.astype(complex)
    n = A.shape[0]
    if n == 0:
        return A.copy()
    # Handle trivial 1x1 quickly
    if n == 1:
        return np.sqrt(A)

    normA = la.norm(A, np.inf)
    if normA == 0:
