import numpy as np, scipy.linalg as la, time, math, random

def sqrt_newton(A, max_iter=20, tol=1e-10):
    # Higham scaled Newton method based on 4^m scaling
    A = A.astype(complex)
    n = A.shape[0]
    if n == 1:
        return np.sqrt(A)
    normA = la.norm(A, np.inf)
    if normA == 0:
        return np.zeros_like(A)
    m = 0
    A_scaled = A.copy()
    while normA > 1.0:
        A_scaled /= 4.0
        m += 1
        normA /= 4.0
    # Not adjusting for small values
    X = A_scaled.copy()
    for k in range(max_iter):
        X_inv = la.inv(X)
        X_next = 0.5 * (X + A_scaled @ X_inv)
        if la.norm(X_next - X, 'fro') <= tol * la.norm(X_next, 'fro'):
            X = X_next
            break
        X = X_next
    X *= (2 ** m)
    return X

for n in [5,10,30,90]:
    ok=True
    for t in range(100):
        A=np.random.randn(n,n)+1j*np.random.randn(n,n)
        X=sqrt_newton(A)
