def sqrt_newton_right(A, max_iter=25, tol=1e-12):
    A = np.asarray(A, dtype=complex)
    n = A.shape[0]
    if n == 0:
        return A.copy()
    if n == 1:
        return np.sqrt(A)
    normA = la.norm(A, np.inf)
    if normA == 0:
        return np.zeros_like(A)
    s = max(0, int(math.ceil(math.log(normA, 4))))
    A_scaled = A / (4**s)
    X = A_scaled.copy()
    I = np.eye(n, dtype=complex)
    for k in range(max_iter):
        X_inv = la.solve(X, I)
        Y = A_scaled @ X_inv  # right version
        X_next = 0.5 * (X + Y)
        if la.norm(X_next - X, ord='fro') <= tol * la.norm(X_next, ord='fro'):
            X = X_next
            break
        X = X_next
    if s:
        X *= (2**s)
