import numpy as np, scipy.linalg as la, math, time

def db_sqrt_fast(A, tol=1e-12, max_iter=10):
    # Denman-Beavers iteration with scaling described by Higham 1997 to reduce iterations
    A = np.asarray(A, dtype=complex)
    n = A.shape[0]
    if n == 0:
        return A.copy()
    # Initial scaling: Find s s.t. norm(A) in [1/4, 1]
    normA = la.norm(A, np.inf)
    if normA == 0:
        return np.zeros_like(A)
    s = max(0, int(math.ceil(math.log(normA, 4))))
    A_s = A / (4**s)
    Y = A_s.copy()
    Z = np.eye(n, dtype=complex)
    I = Z
    for k in range(max_iter):
        Y_inv = la.solve(Z, I)  # Actually we need Z_k^{-1}
        Y_next = 0.5 * (Y + Y_inv)
        Z_inv = la.solve(Y, I)  # Y_k^{-1}
        Z_next = 0.5 * (Z + Z_inv)
        if la.norm(Y_next - Y, ord='fro') <= tol * la.norm(Y_next, ord='fro'):
            Y = Y_next
            Z = Z_next
            break
        Y, Z = Y_next, Z_next
    # Unscale
    Y *= (2 ** s)
    return Y

# quick test
for n in [5,10,30,90]:
    ok=True
    for i in range(50):
        A=np.random.randn(n,n)+1j*np.random.randn(n,n)
        X=db_sqrt_fast(A, max_iter=15)
        if not np.allclose(X@X, A, rtol=1e-5, atol=1e-8):
            ok=False; print('fail',n)
            break
    print(n, ok)
