import numpy as np, random, math, time, numba, scipy.stats as stats
@numba.njit
def ks_d(sorted1, sorted2):
    n1 = sorted1.size
    n2 = sorted2.size
    i1 = i2 = 0
    c1 = c2 = 0
    d = 0.0
    while i1 < n1 and i2 < n2:
        x1 = sorted1[i1]
        x2 = sorted2[i2]
        if x1 <= x2:
            # advance all sample1 values equal to x1
            while i1 < n1 and sorted1[i1] == x1:
                i1 += 1
            c1 = i1
        if x2 <= x1:
            while i2 < n2 and sorted2[i2] == x2:
                i2 += 1
            c2 = i2
        diff = c1 / n1 - c2 / n2
        if diff < 0:
            diff = -diff
        if diff > d:
            d = diff
    # After one sample finished, remaining sample's CDF goes to 1.
    if i1 < n1:
        diff_end = abs(1.0 - c2 / n2)
        if diff_end > d:
            d = diff_end
    elif i2 < n2:
        diff_end = abs(c1 / n1 - 1.0)
        if diff_end > d:
            d = diff_end
    return d

def fast_ks(sample1, sample2):
    a = np.asarray(sample1, dtype=np.float64)
    b = np.asarray(sample2, dtype=np.float64)
    a.sort()
    b.sort()
    d = ks_d(a, b)
    neff = a.size * b.size / (a.size + b.size)
    from scipy.stats import kstwobign
    p = kstwobign.sf((math.sqrt(neff) + 0.12 + 0.11 / math.sqrt(neff)) * d)
    return d, p

# Quick random tests
for n in [1,2,5,10,100,1000]:
    for _ in range(10):
        x = np.random.standard_normal(n)
        y = np.random.standard_normal(n)
        d_ref, p_ref = stats.ks_2samp(x, y, method='asymp').statistic, stats.ks_2samp(x,y,method='asymp').pvalue
        d2, p2 = fast_ks(x,y)
        if abs(d_ref - d2) > 1e-12 or abs(p_ref - p2)/p_ref if p_ref else abs(p2-p_ref) > 1e-12:
            print('Mismatch', n)
            print(d_ref, d2, p_ref, p2)
            raise SystemExit
print('All ok')
