@numba.njit
def ks_d(a,b):
    n1=a.size
    n2=b.size
    i=j=0
    d=0.0
    while i<n1 and j<n2:
        if a[i] <= b[j]:
            val=a[i]
            while i<n1 and a[i]==val:
                i+=1
        else:
            val=b[j]
            while j<n2 and b[j]==val:
                j+=1
        diff=i/n1 - j/n2
        if diff<0:
            diff=-diff
        if diff>d:
            d=diff
    if i<n1:
        diff=1.0 - j/n2
        if diff<0:
            diff=-diff
        if diff>d:
